import { createHash } from 'node:crypto';
import { ExtensionError } from '@yunsoft/yuncms-extensions-sdk';

export default async function (data) {
  const lines = data.$trigger.body?.lines;
  if (!Array.isArray(lines) || !lines.length || lines.length > 100 || lines.some(line =>
    !Number.isInteger(line.quantity) || line.quantity < 1 || line.quantity > 1000 ||
    !Number.isInteger(line.unit_price_cents) || line.unit_price_cents < 0 || line.unit_price_cents > 1000000)) {
    throw new ExtensionError('ORDER_INVALID', 'Provide 1 to 100 valid order lines.', { status: 422 });
  }
  return {
    total_cents: lines.reduce((sum, line) => sum + line.quantity * line.unit_price_cents, 0),
    fingerprint: createHash('sha256').update(JSON.stringify(lines)).digest('hex')
  };
}
